INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wu-chunqiu','吴','["吴","吴国"]',NULL,'{"periods":[{"rank":"伯","start":{"year":-1100,"month":1,"confidence":"year"},"end":{"year":-586,"month":12,"confidence":"approximate_year"}},{"rank":"王","start":{"year":-585,"month":1,"confidence":"approximate_year"},"end":{"year":-473,"month":12,"confidence":"month"}}]}','cn','east_asia',-1100,1,NULL,'year',-473,12,NULL,'month',-13188,-5653,'ochre',NULL,NULL,'传世世系上溯至泰伯；《史记·吴太伯世家》记载武王克殷时周章已君吴，本项目以西周建国年（前1046）为周章起年确定锚点。锚点前后的无年表连续君主分别按世系均分，失考边标为 interpolated；寿梦起始保留前585年年表锚点。前473年越灭吴。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-chai','夫差','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','阖闾之子，数次伐越。夫椒战后为勾践所灭，吴国亡，夫差自杀，霸业终结，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王夫差"}]',NULL,NULL,'夫差','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('helu','阖闾','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','弑僚自立，任用伍子胥、孙武。破楚入郢，与越王勾践争霸，战死槜李，吴国霸业奠基，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阖闾"}]',NULL,NULL,'阖闾','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-wu','孙武','wu-chunqiu','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["军事家"]','齐国军事家，著《孙子兵法》，传为吴王阖闾将；《史记》称他向阖闾进呈兵法并训练吴军；其生平记载有限，兵书作者身份亦有学术讨论。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙武"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-fu-gai','夫概','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','阖闾之弟。前505年自立为吴王，不久败走楚国；见吴国君主列表。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王夫概"}]',NULL,NULL,'夫概','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-pre-r0','泰伯','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','《史记·吴太伯世家》称泰伯与弟仲雍避让季历，奔荆蛮并自号句吴；当地人归附后推立泰伯。史书以此作为吴统绪的开端。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/泰伯"},{"label":"《史记·吴太伯世家》（中国哲学书电子化计划）","url":"https://ctext.org/shiji/wu-tai-bo-shi-jia/zhs"}]',NULL,NULL,'泰伯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-pre-r1','仲雍','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','仲雍是周太王之子、泰伯之弟。泰伯无子而卒后，仲雍继立；《史记》记其后由儿子季简承统，未载其具体政事与在位年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/仲雍"},{"label":"《史记·吴太伯世家》（中国哲学书电子化计划）","url":"https://ctext.org/shiji/wu-tai-bo-shi-jia/zhs"}]',NULL,NULL,'仲雍','[]');
