INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-r1','遏','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','寿梦之子，依遗命实行兄终弟及。战死传位弟余祭，吴国继续扩张，国势强盛，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王诸樊"}]',NULL,NULL,'诸樊','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-r2','余祭','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','诸樊之弟，在位仅三年。继续实行兄终弟及，传位余昧，国势平稳，维持扩张，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王余祭"}]',NULL,NULL,'余祭','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-r3','余眛','wu-chunqiu','[]','姬','姑发',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','余祭之弟，在位十六年。兄终弟及末代，传位诸樊子僚，吴国政局动荡不安，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吴王余昧"}]',NULL,NULL,'余昧','[]');
