INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('wu-shoumeng-assumes-kingship','吴寿梦称王','politics','point','approximate_year',NULL,NULL,'据寿梦即位年定位；《史记》未给独立称王年月，不断言称王仪式就在即位当年。',-585,12,NULL,-6997,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'约-585年，寿梦继位，吴国进入国势扩张并采用王号的阶段。《史记》将“吴始益大，称王”与寿梦即位相连；其后晋国派申公巫臣通吴，传授用兵、乘车之法，吴与中原诸国交往增多，并与楚争衡。王号表达吴君的政治地位，不能视为周天子的升爵册命。',NULL,NULL,'[{"label":"《史记·吴太伯世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷031"}]');
